import React, { useState, useEffect } from 'react';
import { getFranchises, updateExamData } from '../services/api'; // Assuming you have a `getFranchises` function

const ExamData = () => {
  const [franchiseId, setFranchiseId] = useState('');
  const [franchises, setFranchises] = useState([]); // Store the list of franchises
  const [formData, setFormData] = useState({
    examName: '',
    date: '',
    studentsAttended: '',
  });
  const [examDataList, setExamDataList] = useState([]); // Store the list of exam data

  // Fetch franchises on component mount
  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises(); // Assuming this function fetches the list of franchises
        setFranchises(response.data); // Assuming the response contains an array of franchises
      } catch (error) {
        console.error('Error fetching franchises:', error);
        alert('Failed to fetch franchises');
      }
    };

    fetchFranchises();
  }, []); // Empty dependency array ensures it only runs once when the component mounts

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleFranchiseChange = (e) => {
    setFranchiseId(e.target.value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await updateExamData(franchiseId, formData); // Pass franchiseId along with form data
      alert('Exam data updated successfully!');
      setExamDataList([...examDataList, { ...formData, franchiseId }]); // Add the new exam data to the list
      // Reset the form data
      setFormData({
        examName: '',
        date: '',
        studentsAttended: '',
      });
      setFranchiseId('');
    } catch (error) {
      alert('Error updating exam data: ' + (error.response?.data?.message || error.message));
      console.error('Error:', error); // Debugging: Log error
    }
  };

  return (
    <div>
      <h1>Manage Exam Data</h1>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="franchiseId">Franchise ID:</label>
          <select
            id="franchiseId"
            name="franchiseId"
            value={franchiseId}
            onChange={handleFranchiseChange}
            required
          >
            <option value="">Select Franchise</option>
            {franchises.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name} {/* Or whatever property represents the name */}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label htmlFor="examName">Exam Name:</label>
          <input
            id="examName"
            name="examName"
            placeholder="Enter Exam Name"
            value={formData.examName}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="date">Date:</label>
          <input
            id="date"
            name="date"
            type="date"
            value={formData.date}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="studentsAttended">Students Attended:</label>
          <input
            id="studentsAttended"
            name="studentsAttended"
            type="number"
            placeholder="Number of Students"
            value={formData.studentsAttended}
            onChange={handleChange}
            required
          />
        </div>
        <button type="submit">Update Exam Data</button>
      </form>

      <h2>Exam Data</h2>
      {examDataList.length > 0 ? (
        <table border="1">
          <thead>
            <tr>
              <th>Franchise ID</th>
              <th>Exam Name</th>
              <th>Date</th>
              <th>Students Attended</th>
            </tr>
          </thead>
          <tbody>
            {examDataList.map((exam, index) => (
              <tr key={index}>
                <td>{exam.franchiseId}</td>
                <td>{exam.examName}</td>
                <td>{exam.date}</td>
                <td>{exam.studentsAttended}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No exam data available.</p>
      )}
    </div>
  );
};

export default ExamData;
